    private Channel channel;

    @Mock
    private SocketAddress remoteAddress;

    @Mock
    private Protocol protocol;

    public static final String MSG = "Hello, world!";
    public static final String POSITION = "{\"latitude\": 37.7749, \"longitude\": -122.4194}";
    public static final String LIST Devices = "[{\"device1\": {\"id\": 1, \"name\": \"device1\"}, {\"device2\": {\"id\": 2, \"name\": \"device2\"}}]";

    @Test
    public void testDecode_Galileo() {
        BaseProtocolDecoder decoder = new GalileoProtocolDecoder(protocol);
        String result = decoder.decode("192.168.1.100:1234", remoteAddress, MSG);
        assertNotNull(result);
        assertEquals(192.168 .1 .100, result);
    }

    @Test
    public void testDecode_Galileo_Position() {
        BaseProtocolDecoder decoder = new GalileoProtocolDecoder(protocol);
        String result = decoder.decode("192.168.1.100:1234", remoteAddress, POSITION);
        assertNotNull(result);
        assertEquals(POSITION, result);
    }

    @Test
    public void testDecode_Galileo_ListDevices() {
        BaseProtocolDecoder decoder = new GalileoProtocolDecoder(protocol);
        String result = decoder.decode("192.168.1.100:1234", remoteAddress, LIST_DEVICES);
        assertNotNull(result);
        assertEquals(LIST_DEVICES, result);
    }

    @Test
    public void testDecode_Galileo_NoEvents() {
        BaseProtocolDecoder decoder = new GalileoProtocolDecoder(protocol);
        String result = decoder.decode("192.168.1.100:1234", remoteAddress, new Object[]{});
        assertNull(result);
    }

    @Test
    public void testDecode_Galileo_EmptyEvent() {
        BaseProtocolDecoder decoder = new GalileoProtocolDecoder(protocol);
        String result = decoder.decode("192.168.1.100:1234", remoteAddress, new Object[]{-1});
        assertNull(result);
    }

    @Test
    public void testDecode_Galileo_MismatchedEvent() {
        BaseProtocolDecoder decoder = new GalileoProtocolDecoder(protocol);
        try {
            decoder.decode("192.168.1.100:1234", remoteAddress, new Object[]{"timestamp": 1643723400});
            fail("Expected exception");
        } catch (Exception e) {
            // Expect exception
        }
    }

    @Test
    public void testDecode_Galileo_EventWithTimestamp() {
        BaseProtocolDecoder decoder = new GalileoProtocolDecoder(protocol);
        String result = decoder.decode("192.168.1.100:1234", remoteAddress, new Object[]{{"timestamp": 1643723400L}});
        assertNotNull(result);
        assertEquals(POSITION, result);
    }
}
